{
  "verses": [
    {
      "chapter": 3,
      "text_ar": "ولما حضرت ساعة الليل، صعد إرميا وباروخ معاً إلى أسوار المدينة، كما أمر الرب إرميا.",
      "verse": 1
    },
    {
      "chapter": 3,
      "text_ar": "وكان هناك صوت أبواق، وخرجت ملائكة من السماء وفي أيديهم مشاعل، فوضعوها على أسوار المدينة.",
      "verse": 2
    },
    {
      "chapter": 3,
      "text_ar": "ولما رآهما إرميا وباروخ بكيا قائلين: «الآن عرفنا أن الكلمة صادقة!»",
      "verse": 3
    },
    {
      "chapter": 3,
      "text_ar": "وتوسل إرميا إلى الملائكة قائلاً: «أرجوكم، لا تهدموا المدينة بعد، حتى أقول شيئاً للرب».",
      "verse": 4
    },
    {
      "chapter": 3,
      "text_ar": "وتكلم الرب مع الملائكة قائلاً: «لا تهدموا المدينة حتى أتكلم مع مختاري إرميا».",
      "verse": 5
    }
  ],
  "book_code": "4BAR"
}
